namespace RonSijm.FluidHumidifier.Factories.ResilienceHubV2;

public class ServiceFactory(string resourceName = null, Action<Humidifier.ResilienceHubV2.Service> factoryAction = null) : ResourceFactory<Humidifier.ResilienceHubV2.Service>(resourceName)
{

    internal List<InnerServiceAssociatedSystemFactory> AssociatedSystemsFactories { get; set; } = [];

    internal List<InnerServiceAssertionDefinitionFactory> AssertionsFactories { get; set; } = [];

    internal List<InnerServiceInputSourceDefinitionFactory> InputSourcesFactories { get; set; } = [];

    internal InnerServicePermissionModelFactory PermissionModelFactory { get; set; }

    internal InnerServiceServiceReportConfigurationFactory ReportConfigurationFactory { get; set; }

    internal InnerServiceDevOpsAgentConfigurationFactory DevOpsAgentConfigurationFactory { get; set; }

    protected override Humidifier.ResilienceHubV2.Service Create()
    {
        var serviceResult = CreateService();
        factoryAction?.Invoke(serviceResult);

        return serviceResult;
    }

    private Humidifier.ResilienceHubV2.Service CreateService()
    {
        var serviceResult = new Humidifier.ResilienceHubV2.Service
        {
            GivenName = InputResourceName,
        };

        return serviceResult;
    }
    public override void CreateChildren(Humidifier.ResilienceHubV2.Service result)
    {
        base.CreateChildren(result);

        result.AssociatedSystems = AssociatedSystemsFactories.Any() ? AssociatedSystemsFactories.Select(x => x.Build()).ToList() : null;
        result.Assertions = AssertionsFactories.Any() ? AssertionsFactories.Select(x => x.Build()).ToList() : null;
        result.InputSources = InputSourcesFactories.Any() ? InputSourcesFactories.Select(x => x.Build()).ToList() : null;
        result.PermissionModel ??= PermissionModelFactory?.Build();
        result.ReportConfiguration ??= ReportConfigurationFactory?.Build();
        result.DevOpsAgentConfiguration ??= DevOpsAgentConfigurationFactory?.Build();
    }

} // End Of Class

